parameters.jsCode:
// Student message

const studentInput =
$('voice with AI').first().json.body.text || null;

// Router output

const routerEngine =
JSON.parse($('router').first().json.output[0].content[0].text).engine || null;

// Laboratory state

const laboratoryState =
$input.first().json.current_state || null;

// Complete Friday response

const friday =
$('request to friday').first().json.output || {};

// Final normalized object

return [
{
json:{

student_input: studentInput,

laboratory_state: laboratoryState,

came_from: routerEngine,

state_module: friday.state_module || null,

friday_context:{

mission_context:
friday.mission_context || null,

assessment_context: friday.assesment_objective || null,

memory_context:
friday.memory_context || null,

profile_context:
friday.profile_context || null,

curiosity_context:
friday.curiosity_context || null,

science_context:
friday.science_context || null,

testing_context:
friday.testing_context || null,

world_context:
friday.world_context || null,

manipulation_context:
friday.manipulation_context || null

}

}
}
];

